        'c01',
        'CA-005 — GUIDANCE — California replacement — advance warning sign spacing',
        'CA MUTCD §6B.04 para. 07; Table 6B-1; PDF p. 133, 140; printed p. 1223, 1230\\.',
        'GUIDANCE',
        'In California, Table 6B-1 replaces the federal low/high urban speed categories and agency-selected category footnote in Z-026 with the following numeric bands and intermediate rows. It deletes “Minimum” from the title. Distances remain approximate guidance and should be applied with engineering judgment and field adjustment.\n\n| Roadway / speed | A (ft) | B (ft) | C (ft) |\n| :---- | :---- | :---- | :---- |\n| Urban, 25 mph or less | 100 | 100 | 100 |\n| Urban, 30 mph | 150 | 150 | 150 |\n| Urban, 35 mph | 200 | 200 | 200 |\n| Urban, 40 mph | 250 | 250 | 250 |\n| Urban, 45 mph | 300 | 300 | 300 |\n| Urban, 50 mph or more | 350 | 350 | 350 |\n| Rural | 500 | 500 | 500 |\n| Freeway/expressway | 1,000 | 1,500 | 2,640 |\n\nSpeed is posted speed limit, pre-work off-peak 85th-percentile speed, or other anticipated operating speed, in mph. A/B/C retain Z-026’s endpoint definitions.',
        'mutcd.CA-005',
        'source_blocked',
        ('The source flags a footnote error and supplies no interpolation rule between urban speed rows.', 'Schema 1.0.0 does not encode roadway class and State-highway ownership; responsible-agency approval and documented engineering decisions; roadway applicability, approach inventory, and warning-sign/closure associations required by CA-005 (California replacement — advance warning sign spacing).', 'Source reviewer note: No interpolation instruction covers speeds between listed urban bands. Footnote \\*\\*\\*\\* flags an error in footnote \\*\\*; the referenced FHWA known-error list is unavailable.'),
