        'GUIDANCE',
        'For offset W \\= 12 feet, the listed taper lengths should be used under Table 6B-3(CA). The lookup supplements the unchanged federal formulas and taper-type criteria.\n\n| S (mph) | Merging L (ft) | Shifting L/2 (ft) | Shoulder L/3 (ft) | Downstream minimum (ft) |\n| :---- | :---- | :---- | :---- | :---- |\n| 20 | 80 | 40 | 27 | 50 |\n| 25 | 125 | 63 | 42 | 50 |\n| 30 | 180 | 90 | 60 | 50 |\n| 35 | 245 | 123 | 82 | 50 |\n| 40 | 320 | 160 | 107 | 50 |\n| 45 | 540 | 270 | 180 | 50 |\n| 50 | 600 | 300 | 200 | 50 |\n| 55 | 660 | 330 | 220 | 50 |\n| 60 | 720 | 360 | 240 | 50 |\n| 65 | 780 | 390 | 260 | 50 |\n| 70 | 840 | 420 | 280 | 50 |\n| 75 | 900 | 450 | 300 | 50 |\n\nL \\= taper length in feet; W \\= width of offset in feet; S \\= posted speed limit, off-peak 85th-percentile speed prior to work starting, or anticipated operating speed, in mph. Printed rounded values are retained exactly.',
